import{_ as a,o as s,c as e,ag as n}from"./chunks/framework.VvOSaRrC.js";const u=JSON.parse('{"title":"Structured Task Format","description":"","frontmatter":{},"headers":[],"relativePath":"en/task-format.md","filePath":"en/task-format.md"}'),i={name:"en/task-format.md"};function o(r,t,l,p,d,c){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="structured-task-format" tabindex="-1">Structured Task Format <a class="header-anchor" href="#structured-task-format" aria-label="Permalink to &quot;Structured Task Format&quot;">​</a></h1><blockquote><p>Systematic task decomposition with 5-field structure and quality checkpoints.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Every implementation task in KRoot-ADK can be decomposed into structured units with clear acceptance criteria. This format ensures nothing is forgotten, progress is trackable, and quality is verified at regular intervals.</p><hr><h2 id="task-structure-5-fields" tabindex="-1">Task Structure (5 Fields) <a class="header-anchor" href="#task-structure-5-fields" aria-label="Permalink to &quot;Task Structure (5 Fields)&quot;">​</a></h2><p>Each task follows this mandatory format:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Task N: [Title]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do:        What to implement (specific action)</span></span>
<span class="line"><span>Files:     Which files to create or modify</span></span>
<span class="line"><span>Done when: Measurable acceptance criteria</span></span>
<span class="line"><span>Verify:    How to verify completion (test command, manual check)</span></span>
<span class="line"><span>Commit:    Commit message when task is complete</span></span></code></pre></div><h3 id="field-descriptions" tabindex="-1">Field Descriptions <a class="header-anchor" href="#field-descriptions" aria-label="Permalink to &quot;Field Descriptions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><strong>Do</strong></td><td>Yes</td><td>Single, actionable implementation step</td></tr><tr><td><strong>Files</strong></td><td>Yes</td><td>Explicit file paths (create/modify/delete)</td></tr><tr><td><strong>Done when</strong></td><td>Yes</td><td>Measurable criteria (test passes, build succeeds, output matches)</td></tr><tr><td><strong>Verify</strong></td><td>Yes</td><td>Concrete verification command or check</td></tr><tr><td><strong>Commit</strong></td><td>Yes</td><td>Conventional commit message (feat/fix/refactor/test/docs)</td></tr></tbody></table><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Task 1: Create user authentication API</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do:        Implement POST /api/auth/login endpoint with JWT token generation</span></span>
<span class="line"><span>Files:     src/api/auth/login.ts (create), src/types/auth.ts (create)</span></span>
<span class="line"><span>Done when: POST /api/auth/login returns 200 with valid JWT for correct credentials, 401 for invalid</span></span>
<span class="line"><span>Verify:    npm test -- --grep &quot;auth login&quot; passes</span></span>
<span class="line"><span>Commit:    feat(auth): add login endpoint with JWT generation</span></span></code></pre></div><hr><h2 id="quality-checkpoints-verify" tabindex="-1">Quality Checkpoints ([VERIFY]) <a class="header-anchor" href="#quality-checkpoints-verify" aria-label="Permalink to &quot;Quality Checkpoints ([VERIFY])&quot;">​</a></h2><p>Insert a <code>[VERIFY]</code> checkpoint task after every 2-3 implementation tasks.</p><h3 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### Task N: [VERIFY] Quality Checkpoint</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Do:        Run full verification suite</span></span>
<span class="line"><span>Files:     (none - verification only)</span></span>
<span class="line"><span>Done when: All checks pass with zero errors</span></span>
<span class="line"><span>Verify:</span></span>
<span class="line"><span>  - Build passes (zero errors)</span></span>
<span class="line"><span>  - Tests pass (all green)</span></span>
<span class="line"><span>  - Lint clean (zero warnings)</span></span>
<span class="line"><span>  - Manual: feature works as expected</span></span>
<span class="line"><span>Commit:    (no commit - checkpoint only)</span></span></code></pre></div><h3 id="checkpoint-rules" tabindex="-1">Checkpoint Rules <a class="header-anchor" href="#checkpoint-rules" aria-label="Permalink to &quot;Checkpoint Rules&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rule</th><th>Description</th></tr></thead><tbody><tr><td><strong>Frequency</strong></td><td>Insert [VERIFY] after every 2-3 tasks</td></tr><tr><td><strong>Blocking</strong></td><td>Do NOT proceed if checkpoint fails</td></tr><tr><td><strong>Fix First</strong></td><td>Create fix tasks before continuing</td></tr><tr><td><strong>No Skip</strong></td><td>[VERIFY] tasks cannot be skipped or deferred</td></tr><tr><td><strong>Final</strong></td><td>Always insert [VERIFY] as the last task</td></tr></tbody></table><h3 id="insertion-pattern" tabindex="-1">Insertion Pattern <a class="header-anchor" href="#insertion-pattern" aria-label="Permalink to &quot;Insertion Pattern&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task 1: Implementation</span></span>
<span class="line"><span>Task 2: Implementation</span></span>
<span class="line"><span>Task 3: Implementation</span></span>
<span class="line"><span>Task 4: [VERIFY] Quality Checkpoint     ← after 3 tasks</span></span>
<span class="line"><span>Task 5: Implementation</span></span>
<span class="line"><span>Task 6: Implementation</span></span>
<span class="line"><span>Task 7: [VERIFY] Quality Checkpoint     ← after 2 tasks</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>Task N: [VERIFY] Final Checkpoint       ← always at the end</span></span></code></pre></div><hr><h2 id="ddd-task-variant" tabindex="-1">DDD Task Variant <a class="header-anchor" href="#ddd-task-variant" aria-label="Permalink to &quot;DDD Task Variant&quot;">​</a></h2><p>When working with existing code (DDD workflow), tasks use ANALYZE/PRESERVE/IMPROVE prefixes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task 1: [ANALYZE] Understand current auth flow</span></span>
<span class="line"><span>Task 2: [PRESERVE] Add characterization tests</span></span>
<span class="line"><span>Task 3: [IMPROVE] Refactor to JWT-based auth</span></span>
<span class="line"><span>Task 4: [VERIFY] Quality Checkpoint</span></span></code></pre></div><hr><h2 id="task-sizing-guidelines" tabindex="-1">Task Sizing Guidelines <a class="header-anchor" href="#task-sizing-guidelines" aria-label="Permalink to &quot;Task Sizing Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Size</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>XS</strong></td><td>Single function/method</td><td>Add validation helper</td></tr><tr><td><strong>S</strong></td><td>Single file change</td><td>Create API endpoint</td></tr><tr><td><strong>M</strong></td><td>2-3 file changes</td><td>Feature with tests</td></tr><tr><td><strong>L</strong></td><td>4+ file changes</td><td><strong>Split into smaller tasks</strong></td></tr></tbody></table><p><strong>Rule</strong>: If a task touches more than 3 files, split it into smaller tasks.</p><hr><h2 id="todowrite-integration" tabindex="-1">TodoWrite Integration <a class="header-anchor" href="#todowrite-integration" aria-label="Permalink to &quot;TodoWrite Integration&quot;">​</a></h2><p>All tasks are tracked using TodoWrite for real-time progress:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Task discovered  → TodoWrite: add with &quot;pending&quot; status</span></span>
<span class="line"><span>Task started     → TodoWrite: change to &quot;in_progress&quot;</span></span>
<span class="line"><span>Task completed   → TodoWrite: change to &quot;completed&quot;</span></span>
<span class="line"><span>[VERIFY] failed  → TodoWrite: add fix tasks with &quot;pending&quot;</span></span></code></pre></div><hr><h2 id="integration-with-workflows" tabindex="-1">Integration with Workflows <a class="header-anchor" href="#integration-with-workflows" aria-label="Permalink to &quot;Integration with Workflows&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>How Task Format is Used</th></tr></thead><tbody><tr><td><strong>POC-First</strong></td><td>Each phase generates tasks in this format</td></tr><tr><td><strong>TDD</strong></td><td>RED-GREEN-REFACTOR maps to task sequences</td></tr><tr><td><strong>DDD</strong></td><td>ANALYZE-PRESERVE-IMPROVE maps to task prefixes</td></tr><tr><td><strong>Ralph Loop</strong></td><td>Loop iterations track progress via TodoWrite</td></tr></tbody></table><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="./poc-first.html">POC-First Workflow</a> — Phase-based greenfield development</li><li><a href="./pr-lifecycle.html">PR Lifecycle Automation</a> — PR management automation</li><li><a href="./tdd-ddd.html">TDD &amp; DDD Workflow</a> — Alternative development methodologies</li></ul>`,39)])])}const k=a(i,[["render",o]]);export{u as __pageData,k as default};
